import{_ as e,o as t,c as o,a6 as i}from"./chunks/framework.B_q3ZJNF.js";const f=JSON.parse('{"title":"激活、命令与生命周期：别拖慢所有人的启动","description":"","frontmatter":{"title":"激活、命令与生命周期：别拖慢所有人的启动"},"headers":[],"relativePath":"vscode-iconify-course/12-activation-lifecycle.md","filePath":"vscode-iconify-course/docs/12-activation-lifecycle.md"}'),c={name:"vscode-iconify-course/12-activation-lifecycle.md"};function r(n,a,l,s,d,p){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="激活、命令与生命周期-别拖慢所有人的启动" tabindex="-1">激活、命令与生命周期：别拖慢所有人的启动 <a class="header-anchor" href="#激活、命令与生命周期-别拖慢所有人的启动" aria-label="Permalink to &quot;激活、命令与生命周期：别拖慢所有人的启动&quot;">​</a></h1><p>一个图标扩展在公司内部市场上线，三个月后两封工单同时到达。第一封来自行政：「装了你们的插件，我的 VSCode 启动慢了两秒」——激活事件写成了「任何情况都加载」，打开一个纯文档窗口也要初始化图标引擎。第二封更微妙：「globalStorage 目录两百多兆，能删吗？」——三个月的图标缓存无人治理，也没有清理入口。回望第 1 章那个让全员启动慢 800 毫秒的 TODO 插件：生命周期不是收尾的杂务，<strong>它是用户对你的第一印象和最后印象</strong>。最后一章把扩展的边界画完整，然后回望全书管线。</p><h2 id="激活-为谁加载、何时加载" tabindex="-1">激活：为谁加载、何时加载 <a class="header-anchor" href="#激活-为谁加载、何时加载" aria-label="Permalink to &quot;激活：为谁加载、何时加载&quot;">​</a></h2><p>激活事件（Activation Events）的声明写在 package.json 的贡献点（Contribution Point）里，它回答「编辑器在什么时机把你的代码加载进内存」。对一个图标扩展，合理的选择是按语言激活——用户打开 Vue、TypeScript、HTML 这类可能写图标键的文件才加载；再辅以按工作区内容激活，工作区里有 package.json 才加载。两条声明把「打开 README 写文档的人」「看日志的人」全部排除在外——他们不需要你，你就别为他们花启动时间。</p><p>激活之后还有第二层「何时」：激活只加载元数据（第 7 章的分界），图标数据继续惰性等待第一个真实图标键出现。两层惰性叠加，才是完整的启动账：多数用户多数窗口，你的扩展成本接近于零；真用上的用户，也只有第一次碰到新集合时付一次下载钱，之后内存与磁盘接手。</p><p>声明与运行要互相成全。声明了按语言激活，激活时就要快速就位——注册提供方、挂上装饰计算、启动配置监听，都是轻操作；耗时的远程集合拉取应该异步进行，图标到了装饰自然出现，用户不必等一个「加载完成」。真实的扩展框架甚至提供纯声明式的轻量能力（比如片段，只是 JSON 文件，编辑器直接读，扩展代码根本不激活）——能用贡献点解决的，就别用代码解决。</p><h2 id="命令-用户手里的开关" tabindex="-1">命令：用户手里的开关 <a class="header-anchor" href="#命令-用户手里的开关" aria-label="Permalink to &quot;命令：用户手里的开关&quot;">​</a></h2><p>命令是贡献点里最用户可见的一种：命令面板里的「切换注释」「切换 in-place 模式」「清除图标缓存」。三个命令恰好是三种典型的生命周期操作。</p><p>「切换注释」和「切换 in-place」改的是配置项——命令只是配置写入的快捷方式。这里体现第 10 章的直接回报：命令改配置、配置是 ref、装饰跑在 watchEffect 里，命令执行后的重算是自动的，命令处理器里没有一行「刷新」代码。「清除图标缓存」则是缓存治理的入口：内存与磁盘两级说清语义（对应实验场里 <code>clearCache</code> 只清内存的「重新加载」语义），两百兆的工单从此有了用户侧的解药。命令还应该出现在合适的菜单与快捷键里，但那是锦上添花——本质始终是：命令是用户手伸进你生命周期的合法途径。</p><h2 id="生命周期的最后一段" tabindex="-1">生命周期的最后一段 <a class="header-anchor" href="#生命周期的最后一段" aria-label="Permalink to &quot;生命周期的最后一段&quot;">​</a></h2><p>扩展停用的时刻同样属于设计：监听要销毁、watchEffect 要 stop、缓存句柄要释放。第 11 章 <code>dispose</code> 的存在不只为了测试——窗口关闭时逐一调用，才是把「不拖慢」坚持到最后。扩展框架的订阅列表（subscriptions）是统一管理这些句柄的惯例：创建一个推一个，停用时批量释放，不漏不忘。</p><h2 id="全书回望-从一行文本到一枚图标" tabindex="-1">全书回望：从一行文本到一枚图标 <a class="header-anchor" href="#全书回望-从一行文本到一枚图标" aria-label="Permalink to &quot;全书回望：从一行文本到一枚图标&quot;">​</a></h2><p>十二章走完，把整条管线从头到尾串一遍：</p><ol><li><strong>识别</strong>（第 2-4 章）：配置驱动的正则从文本里捞出图标键，偏移换算成行列，解析拆出集合与图标名，别名在解析前展开；</li><li><strong>数据</strong>（第 5-7 章）：集合 id 进三级缓存逐级回源，在途去重保证并发只发一次；裸 SVG 片段穿壳、按宽高比撑开、染上主题色、编码成 data URL；构建期只打包元数据，完整数据运行期按需；</li><li><strong>智能</strong>（第 8-11 章）：装饰描述符汇总一切，in-place 模式光标行不藏字；补全两段式出候选、选中才出大图；依赖追踪让配置与数据源活了，自定义集合热重载贯通全链；</li><li><strong>边界</strong>（本章）：按语言与工作区激活，两层惰性叠加，命令交出开关，停用释放一切。</li></ol><p>你手里现在有一个约七百行、零编辑器依赖的实验场：<code>tsc</code> 零错误、81 条原理断言全绿。它不是任何真实扩展的复刻——但「输入文本与配置，输出装饰、补全与悬停」这条管线，与任何一个真实文本智能扩展的骨架同构。哪天你想给自己的编辑器写一个 TODO 高亮、色板预览、接口名翻译……拆特性、画依赖、选通道、定激活——方法你已经全部用过一遍了。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>激活事件划定「为谁加载」，两层惰性把启动成本压到接近零；命令是用户进出生命周期的合法入口，改配置即自动生效是依赖追踪的直接回报；停用时释放监听与句柄，善始善终。管线从识别到数据到智能到边界，十二章建完——下一次在编辑器里看到一枚内联小图标，你看到的不再是一枚图标，而是一整条你亲手建过的流水线。</p>',17)])])}const u=e(c,[["render",r]]);export{f as __pageData,u as default};
